package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class OffboardingBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  var f=OffboardingAcceptance.seed(h.store,"OffboardBrowser"+id());String source=f.get("source").toString(),route=OffboardingAcceptance.ui(source);
  try(var p=Playwright.create();var browser=p.chromium().launch();var admin=browser.newContext();var departing=browser.newContext();var successor=browser.newContext()) {
   var former=departing.newPage();h.login(former,f.get("from").toString());var page=admin.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/accounts/"+source);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review offboarding handoff").setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("No completed handoff");page.getByLabel("Successor username").fill(f.get("to").toString());ServiceOutagesBrowserAcceptance.click(page,"Review supported handoff");assertThat(page.locator("main")).containsText("Supported departing assignment");assertThat(page.locator("main")).containsText("Departing private report");assertThat(page.locator("main")).not().containsText("Historical completed assignment");page.locator("a[href='/record/incident/"+f.get("record")+"/work-tasks']").press("Enter");assertThat(page.locator("main")).containsText("Continue departed employee work");page.navigate(h.base()+route+"?recipient="+f.get("to"));ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/offboarding-review-light.png")).setFullPage(true));ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertEquals(false,page.evaluate("Array.from(document.querySelectorAll('main .panel')).some(p=>p.scrollWidth>p.clientWidth+1)"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/offboarding-review-dark.png")).setFullPage(true));page.getByLabel("Handoff reason").fill("Reviewed employee departure <script>");ServiceOutagesBrowserAcceptance.click(page,"Hand off supported work and deactivate");assertThat(page.locator("main")).containsText("Account is inactive");assertThat(page.locator("main")).containsText("Core assignments: 1 · Case tasks: 1 · Routed requests: 1 · Report definitions: 1");assertThat(page.locator("main script")).hasCount(0);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/offboarding-receipt-dark.png")).setFullPage(true));former.navigate(h.base()+"/account");former.waitForURL(h.base()+"/login");
   var worker=successor.newPage();h.login(worker,f.get("to").toString());worker.navigate(h.base()+"/record/incident/"+f.get("record")+"/work-tasks");ServiceOutagesBrowserAcceptance.click(worker,"Claim task");worker.getByLabel("Completion outcome").fill("Successor verified continued service");ServiceOutagesBrowserAcceptance.click(worker,"Complete task");assertThat(worker.locator("main")).containsText("Successor verified continued service");worker.navigate(h.base()+"/reports/"+f.get("report"));assertThat(worker.locator("main")).containsText("Edit your report");try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_offboarding WHERE source_id=?",source));assertEquals(f.get("target"),db.one("SELECT owner_id FROM os_saved_report WHERE report_id=?",f.get("report")).get("owner_id"));assertEquals("complete",db.one("SELECT state FROM os_case_task WHERE task_id=?",f.get("task")).get("state"));}
  }
 }
}
